set -e; umask 077; trap 'rm -f /run/branch_stock_credentials.enc /run/branch_stock_credentials /run/branch_stock_transfer.key' EXIT; printf '%s' '[REDACTED_ENCODED_BLOB]' | base64 -d > /run/branch_stock_credentials.enc; openssl pkeyutl -decrypt -inkey /run/branch_stock_transfer.key -pkeyopt rsa_padding_mode:oaep -in /run/branch_stock_credentials.enc -out /run/branch_stock_credentials; . /run/branch_stock_credentials; sudo -u postgres createdb branch_stock; sudo -u postgres psql -v ON_ERROR_STOP=1 -d branch_stock -f /srv/legacy2/database-reader-writer-roles/stock.sql; sudo -u postgres psql -v ON_ERROR_STOP=1 --set=stock_pw="$stock_app" --set=auditor_pw="$auditor" -d branch_stock <<'BRANCH_STOCK_SQL'
CREATE ROLE stock_app LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION PASSWORD :[REDACTED];
CREATE ROLE auditor LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION PASSWORD :[REDACTED];
REVOKE ALL ON DATABASE branch_stock FROM PUBLIC;
GRANT CONNECT ON DATABASE branch_stock TO stock_app, auditor;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO stock_app, auditor;
REVOKE ALL ON TABLE stock, supplier_costs FROM PUBLIC;
GRANT SELECT ON TABLE stock TO stock_app;
GRANT UPDATE (quantity) ON TABLE stock TO stock_app;
GRANT SELECT ON TABLE stock, supplier_costs TO auditor;
BRANCH_STOCK_SQL
unset stock_app auditor; sha256sum /srv/legacy2/database-reader-writer-roles/stock.sql; sudo -u postgres psql -Atqc "SELECT datname FROM pg_database WHERE datname='branch_stock'; SELECT rolname||':'||rolcanlogin||':'||rolsuper||':'||rolcreatedb||':'||rolcreaterole FROM pg_roles WHERE rolname IN ('stock_app','auditor') ORDER BY rolname;"

